import { computed, ref } from "vue";
import type { Router } from "vue-router";

export type CartItem = {
  id: string;
  name: string;
  price: number;
  quantity: number;
};

const items = ref<CartItem[]>([]);

export function useCart() {
  const total = computed(function sum() {
    return items.value.reduce(function addToTotal(value, item) {
      return value + item.price * item.quantity;
    }, 0);
  });

  function add(item: Omit<CartItem, "quantity">) {
    const existing = items.value.find(function byId(entry) {
      return entry.id === item.id;
    });

    if (existing !== undefined) {
      existing.quantity += 1;
      return;
    }

    items.value.push({ ...item, quantity: 1 });
  }

  return { items, total, add };
}

export function installCartGuard(router: Router) {
  router.beforeEach(function guard(to) {
    if (to.meta.requiresCart === true && items.value.length === 0) {
      return { name: "catalog" };
    }
    return true;
  });
}
